package net.civeira.phylax.features.access.userconsentpurposes.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurposeReference;

class ConsentPurposeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property consent purpose of user consent purposes ")
  void test_consent_purpose_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", ConsentPurposeVO.fromReference("10").getConsentPurposeUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", ConsentPurposeVO.tryFromReference("11").getConsentPurposeUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12",
        ConsentPurposeVO.tryFromReference("12", fails).getConsentPurposeUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> ConsentPurposeVO.tryFrom(null));
    Assertions.assertEquals(ConsentPurposeReference.of("one"),
        ConsentPurposeVO.from(ConsentPurposeReference.of("one")).getConsentPurpose());
    Assertions.assertThrows(ConstraintException.class,
        () -> ConsentPurposeVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ConsentPurposeReference.of("one") + "]",
        ConsentPurposeVO.from(ConsentPurposeReference.of("one")).toString());
  }
}
